import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.RycU2wFZ.js";const u=JSON.parse('{"title":"Tool Calling: How Agents Interact with External Systems","description":"","frontmatter":{},"headers":[],"relativePath":"learn/01-agent-basics/tool-calling.md","filePath":"learn/01-agent-basics/tool-calling.md","lastUpdated":1792595354000}'),s={name:"learn/01-agent-basics/tool-calling.md"};function r(i,e,l,c,p,d){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="tool-calling-how-agents-interact-with-external-systems" tabindex="-1">Tool Calling: How Agents Interact with External Systems <a class="header-anchor" href="#tool-calling-how-agents-interact-with-external-systems" aria-label="Permalink to &quot;Tool Calling: How Agents Interact with External Systems&quot;">​</a></h1><p>A language model normally returns text. Tool calling lets an application offer named operations with descriptions and structured inputs. The model can request an operation; the host validates and executes it, then returns the result to the model.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User request → model selects a tool → host validates and runs it</span></span>
<span class="line"><span>             ← tool result        ←</span></span></code></pre></div><p>The model does not execute arbitrary code simply by proposing a call. The application controls which tools exist and whether a request is permitted.</p><p>For example, a weather lookup might be requested as <code>get_weather({&quot;city&quot;:&quot;Singapore&quot;})</code>. The host validates the tool and arguments, calls the service, and passes its result back. Schema validation checks form; authorization checks whether this caller may perform the operation. Both are necessary.</p><p>Use narrowly scoped capabilities. A read-only lookup should not share credentials with an operation that can change records or spend money. Validate arguments at the boundary and use idempotency for operations that may be retried.</p><p>Tools can fail, partially complete, or time out after performing an action. A timeout after a write does not prove the write failed; query or reconcile before retrying. Treat tool output as untrusted data because webpages and API responses may contain prompt injection. Keep authorization independent of model-generated instructions.</p><p><strong>The model proposes an operation; the host owns validation, credentials, authorization, execution, and recovery.</strong></p>`,8)])])}const m=t(s,[["render",r]]);export{u as __pageData,m as default};
